/* Theme Root Overrides */
.edu-dash-root {
  background: #0b1120 !important;
  color: #f8fafc !important;
}

[data-theme="light"] .edu-dash-root,
.edu-dash-root[data-theme="light"],
body[data-theme="light"] .edu-dash-root {
  background: #f8fafc !important;
  color: #0f172a !important;
}

[data-theme="dark"] .edu-dash-root,
.edu-dash-root[data-theme="dark"],
body[data-theme="dark"] .edu-dash-root {
  background: #0b1120 !important;
  color: #f8fafc !important;
}


/* =========================================================================
   ADMISSION FIXES: IN MERIT & ENROLLED DASHBOARD STYLES
   ========================================================================= */

.status-in-merit, .status-in_merit { background: rgba(59, 130, 246, 0.25); color: #60a5fa; box-shadow: 0 0 15px rgba(59, 130, 246, 0.3); }
[data-theme='light'] .status-in-merit, [data-theme='light'] .status-in_merit { background: #dbeafe; color: #1d4ed8; }

/* IN MERIT BANNER */
.edu-merit-banner {
  background: linear-gradient(135deg, rgba(30, 58, 138, 0.5), rgba(59, 130, 246, 0.25));
  border: 2px solid #3b82f6; border-radius: 20px; padding: 26px 32px;
  margin-bottom: 24px; display: flex; align-items: center; gap: 24px;
  box-shadow: 0 8px 24px rgba(59, 130, 246, 0.2);
}
.edu-merit-icon { font-size: 44px; flex-shrink: 0; line-height: 1; }
.edu-merit-info { flex: 1; }
.edu-merit-tag { font-size: 12px; font-weight: 800; color: #93c5fd; letter-spacing: 0.06em; text-transform: uppercase; margin-bottom: 4px; }
.edu-merit-banner h2 { font-size: 22px; font-weight: 800; color: #ffffff; margin: 0 0 6px; }
.edu-merit-banner p { font-size: 15px; color: #bfdbfe; margin: 0; line-height: 1.5; }

[data-theme='light'] .edu-merit-banner {
  background: linear-gradient(135deg, #eff6ff, #dbeafe);
  border-color: #3b82f6; box-shadow: 0 8px 20px rgba(59, 130, 246, 0.12);
}
[data-theme='light'] .edu-merit-tag { color: #1d4ed8; }
[data-theme='light'] .edu-merit-banner h2 { color: #1e3a8a; }
[data-theme='light'] .edu-merit-banner p { color: #1e40af; }

/* ENROLLED HERO CARD */
.edu-enrolled-hero-card {
  background: linear-gradient(135deg, rgba(6, 78, 59, 0.4), rgba(16, 185, 129, 0.2));
  border: 2px solid #10b981; border-radius: 24px; padding: 32px 36px;
  margin-bottom: 24px; box-shadow: 0 8px 28px rgba(16, 185, 129, 0.15);
}
.edu-enrolled-header { display: flex; align-items: center; gap: 20px; margin-bottom: 24px; }
.edu-enrolled-icon-circle {
  width: 58px; height: 58px; border-radius: 50%; background: #10b981;
  display: flex; align-items: center; justify-content: center; font-size: 30px; flex-shrink: 0;
}
.edu-enrolled-titles { flex: 1; }
.edu-enrolled-badge {
  font-size: 12px; font-weight: 800; color: #6ee7b7; letter-spacing: 0.06em;
  text-transform: uppercase; display: inline-block; margin-bottom: 4px;
}
.edu-enrolled-titles h2 { font-size: 24px; font-weight: 800; color: #ffffff; margin: 0 0 6px; }
.edu-enrolled-titles p { font-size: 15px; color: #a7f3d0; margin: 0; }

.edu-enrolled-meta-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px; background: rgba(0, 0, 0, 0.25); border-radius: 16px; padding: 20px;
  border: 1px solid rgba(16, 185, 129, 0.3); margin-bottom: 20px;
}
.edu-enrolled-meta-item { display: flex; flex-direction: column; gap: 4px; }
.edu-meta-label { font-size: 12px; color: #94a3b8; font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; }
.edu-meta-value { font-size: 16px; color: #f8fafc; font-weight: 700; }
.edu-status-active-pill {
  display: inline-block; background: #10b981; color: #ffffff; font-size: 13px;
  font-weight: 800; padding: 2px 10px; border-radius: 12px; align-self: flex-start;
}
.edu-enrolled-footer-note { font-size: 14px; color: #a7f3d0; line-height: 1.6; }

[data-theme='light'] .edu-enrolled-hero-card {
  background: linear-gradient(135deg, #f0fdf4, #dcfce7);
  border-color: #10b981; box-shadow: 0 8px 24px rgba(16, 185, 129, 0.12);
}
[data-theme='light'] .edu-enrolled-badge { color: #047857; }
[data-theme='light'] .edu-enrolled-titles h2 { color: #064e3b; }
[data-theme='light'] .edu-enrolled-titles p { color: #065f46; }
[data-theme='light'] .edu-enrolled-meta-grid {
  background: #ffffff; border-color: #bbf7d0; box-shadow: 0 2px 8px rgba(0,0,0,0.03);
}
[data-theme='light'] .edu-meta-label { color: #64748b; }
[data-theme='light'] .edu-meta-value { color: #0f172a; }
[data-theme='light'] .edu-enrolled-footer-note { color: #166534; }


/* ========================================================================== */
/* REFRESH BUTTON STYLING                                                      */
/* ========================================================================== */
.edu-refresh-btn {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 6px !important;
  padding: 8px 14px !important;
  border-radius: 9999px !important;
  border: 1px solid rgba(255, 255, 255, 0.15) !important;
  background: rgba(255, 255, 255, 0.08) !important;
  color: #f8fafc !important;
  font-size: 13px !important;
  font-weight: 600 !important;
  cursor: pointer !important;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1) !important;
  line-height: 1 !important;
  outline: none !important;
}
.edu-refresh-btn:hover {
  background: rgba(255, 255, 255, 0.16) !important;
  border-color: rgba(255, 255, 255, 0.3) !important;
  transform: translateY(-1px) !important;
}
[data-theme="light"] .edu-refresh-btn {
  background: #f1f5f9 !important;
  border-color: #cbd5e1 !important;
  color: #0f172a !important;
}
[data-theme="light"] .edu-refresh-btn:hover {
  background: #e2e8f0 !important;
  border-color: #94a3b8 !important;
}

/* ========================================================================== */
/* COUNSELLING SECTION & CARDS                                                 */
/* ========================================================================== */
.edu-counselling-section {
  margin: 36px 0 !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 24px !important;
}
.edu-counselling-header {
  margin-bottom: 8px !important;
}
.edu-counselling-header h2 {
  font-size: 26px !important;
  font-weight: 800 !important;
  margin: 10px 0 6px 0 !important;
  letter-spacing: -0.01em !important;
}
.edu-counselling-header p {
  font-size: 15px !important;
  margin: 0 !important;
  opacity: 0.85 !important;
}

/* Summary Card Grid */
.edu-data-grid-3 {
  display: grid !important;
  grid-template-columns: repeat(3, 1fr) !important;
  gap: 20px !important;
  padding: 16px 0 8px 0 !important;
}
@media (max-width: 768px) {
  .edu-data-grid-3 {
    grid-template-columns: 1fr !important;
    gap: 14px !important;
  }
}
.edu-summary-item {
  display: flex !important;
  flex-direction: column !important;
  gap: 4px !important;
}
.edu-label-dim {
  font-size: 12px !important;
  text-transform: uppercase !important;
  letter-spacing: 0.05em !important;
  font-weight: 700 !important;
  opacity: 0.7 !important;
}
.edu-summary-item strong {
  font-size: 15px !important;
  font-weight: 600 !important;
}
.edu-text-gold {
  color: #c2882f !important;
}
[data-theme="dark"] .edu-text-gold {
  color: #fbbf24 !important;
}

/* Counselling Card */
.edu-counsel-card {
  position: relative !important;
  border-radius: 20px !important;
  padding: 28px !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 20px !important;
}
.edu-counsel-card-head {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  flex-wrap: wrap !important;
  gap: 12px !important;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08) !important;
  padding-bottom: 16px !important;
}
[data-theme="light"] .edu-counsel-card-head {
  border-bottom-color: #f1f5f9 !important;
}
.edu-counsel-title-group {
  display: flex !important;
  align-items: center !important;
  gap: 12px !important;
}
.edu-counsel-title-group h3 {
  font-size: 19px !important;
  font-weight: 800 !important;
  margin: 0 !important;
}
.edu-round-tag {
  font-size: 12px !important;
  font-weight: 800 !important;
  padding: 4px 10px !important;
  border-radius: 8px !important;
  background: rgba(194, 136, 47, 0.2) !important;
  color: #fbbf24 !important;
  border: 1px solid rgba(194, 136, 47, 0.4) !important;
}
.edu-round2-tag {
  background: rgba(99, 102, 241, 0.2) !important;
  color: #a5b4fc !important;
  border-color: rgba(99, 102, 241, 0.4) !important;
}

/* Status Pills */
.edu-status-pill {
  display: inline-flex !important;
  align-items: center !important;
  gap: 6px !important;
  font-size: 13px !important;
  font-weight: 700 !important;
  padding: 5px 12px !important;
  border-radius: 9999px !important;
}
.pill-green {
  background: rgba(16, 185, 129, 0.15) !important;
  color: #10b981 !important;
  border: 1px solid rgba(16, 185, 129, 0.3) !important;
}
.pill-amber {
  background: rgba(245, 158, 11, 0.15) !important;
  color: #f59e0b !important;
  border: 1px solid rgba(245, 158, 11, 0.3) !important;
}
.pill-rose {
  background: rgba(239, 68, 68, 0.15) !important;
  color: #ef4444 !important;
  border: 1px solid rgba(239, 68, 68, 0.3) !important;
}
.pill-slate {
  background: rgba(100, 116, 139, 0.15) !important;
  color: #94a3b8 !important;
  border: 1px solid rgba(100, 116, 139, 0.3) !important;
}

/* Details Grid */
.edu-counsel-details-grid {
  display: grid !important;
  grid-template-columns: repeat(3, 1fr) !important;
  gap: 18px !important;
}
@media (max-width: 768px) {
  .edu-counsel-details-grid {
    grid-template-columns: 1fr !important;
    gap: 12px !important;
  }
}
.edu-counsel-item {
  display: flex !important;
  flex-direction: column !important;
  gap: 4px !important;
}
.edu-highlight-val {
  font-size: 16px !important;
  color: #38bdf8 !important;
}
[data-theme="light"] .edu-highlight-val {
  color: #0284c7 !important;
}

/* Decision Badges */
.edu-dec-badge {
  display: inline-block !important;
  font-size: 12.5px !important;
  font-weight: 700 !important;
  padding: 3px 10px !important;
  border-radius: 6px !important;
  width: fit-content !important;
}
.dec-accepted {
  background: rgba(16, 185, 129, 0.2) !important;
  color: #10b981 !important;
}
.dec-rejected {
  background: rgba(239, 68, 68, 0.2) !important;
  color: #ef4444 !important;
}
.dec-pending {
  background: rgba(245, 158, 11, 0.2) !important;
  color: #f59e0b !important;
}

/* Action Required Bar */
.edu-counsel-action-bar {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  flex-wrap: wrap !important;
  gap: 16px !important;
  padding: 20px 24px !important;
  border-radius: 14px !important;
  background: rgba(245, 158, 11, 0.1) !important;
  border: 1.5px solid rgba(245, 158, 11, 0.35) !important;
}
.edu-counsel-action-text {
  display: flex !important;
  align-items: center !important;
  gap: 14px !important;
  flex: 1 !important;
  min-width: 260px !important;
}
.edu-action-icon {
  font-size: 28px !important;
  line-height: 1 !important;
}
.edu-counsel-action-text strong {
  display: block !important;
  font-size: 15px !important;
  color: #fbbf24 !important;
  margin-bottom: 2px !important;
}
.edu-counsel-action-text p {
  margin: 0 !important;
  font-size: 13.5px !important;
  line-height: 1.4 !important;
  opacity: 0.9 !important;
}
.edu-counsel-btns {
  display: flex !important;
  align-items: center !important;
  gap: 12px !important;
  flex-wrap: wrap !important;
}
.edu-btn-accept {
  background: #10b981 !important;
  color: #ffffff !important;
  border: none !important;
  padding: 10px 20px !important;
  font-size: 14px !important;
  font-weight: 700 !important;
  border-radius: 10px !important;
  cursor: pointer !important;
  transition: all 0.2s ease !important;
  box-shadow: 0 4px 14px rgba(16, 185, 129, 0.3) !important;
}
.edu-btn-accept:hover {
  background: #059669 !important;
  transform: translateY(-1px) !important;
}
.edu-btn-decline {
  background: transparent !important;
  color: #ef4444 !important;
  border: 1.5px solid rgba(239, 68, 68, 0.4) !important;
  padding: 9px 18px !important;
  font-size: 14px !important;
  font-weight: 600 !important;
  border-radius: 10px !important;
  cursor: pointer !important;
  transition: all 0.2s ease !important;
}
.edu-btn-decline:hover {
  background: rgba(239, 68, 68, 0.1) !important;
  border-color: #ef4444 !important;
}

/* Alert Boxes */
.edu-alert-box {
  padding: 16px 20px !important;
  border-radius: 12px !important;
  font-size: 14px !important;
  line-height: 1.5 !important;
}
.edu-alert-success {
  background: rgba(16, 185, 129, 0.12) !important;
  border: 1px solid rgba(16, 185, 129, 0.3) !important;
  color: #10b981 !important;
}
.edu-alert-warn {
  background: rgba(245, 158, 11, 0.12) !important;
  border: 1px solid rgba(245, 158, 11, 0.3) !important;
  color: #fbbf24 !important;
}
.edu-alert-info {
  background: rgba(14, 165, 233, 0.12) !important;
  border: 1px solid rgba(14, 165, 233, 0.3) !important;
  color: #38bdf8 !important;
}
.edu-r2-pending-note {
  font-size: 13.5px !important;
  opacity: 0.75 !important;
  padding: 8px 12px !important;
  border-radius: 8px !important;
  background: rgba(255, 255, 255, 0.04) !important;
}

/* Modals */
.edu-modal-summary-box {
  background: rgba(255, 255, 255, 0.05) !important;
  border-radius: 10px !important;
  padding: 14px 18px !important;
  margin: 14px 0 !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 8px !important;
}
[data-theme="light"] .edu-modal-summary-box {
  background: #f8fafc !important;
  border: 1px solid #e2e8f0 !important;
}
.edu-modal-summary-box div {
  display: flex !important;
  justify-content: space-between !important;
  font-size: 14px !important;
}

/* ========================================================================== */
/* DARK THEME HIGH-CONTRAST OVERHAUL                                           */
/* ========================================================================== */
[data-theme="dark"] .edu-dash-root {
  background: #0b1120 !important;
  color: #f8fafc !important;
}
[data-theme="dark"] .edu-card {
  background: rgba(30, 41, 59, 0.7) !important;
  border: 1px solid rgba(51, 65, 85, 0.8) !important;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.35) !important;
  color: #f8fafc !important;
}
[data-theme="dark"] .edu-card-heading {
  color: #ffffff !important;
}
[data-theme="dark"] .edu-card-sub {
  color: #94a3b8 !important;
}
[data-theme="dark"] .edu-data-row span {
  color: #94a3b8 !important;
}
[data-theme="dark"] .edu-data-row strong {
  color: #ffffff !important;
}
[data-theme="dark"] .edu-data-row {
  border-bottom: 1px solid rgba(51, 65, 85, 0.6) !important;
}
[data-theme="dark"] .edu-doc-item,
[data-theme="dark"] .edu-doc-row {
  background: rgba(15, 23, 42, 0.6) !important;
  border: 1px solid rgba(51, 65, 85, 0.6) !important;
}
[data-theme="dark"] .edu-doc-title {
  color: #ffffff !important;
}
[data-theme="dark"] .edu-modal-box {
  background: #1e293b !important;
  border: 1px solid #334155 !important;
  color: #f8fafc !important;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.6) !important;
}
[data-theme="dark"] .edu-modal-head h3 {
  color: #ffffff !important;
}
[data-theme="dark"] .edu-modal-body p {
  color: #cbd5e1 !important;
}

/* ========================================================================== */
/* LIGHT THEME EXPLICIT REFINEMENT                                             */
/* ========================================================================== */
[data-theme="light"] .edu-dash-root {
  background: #f8fafc !important;
  color: #0f172a !important;
}
[data-theme="light"] .edu-card {
  background: #ffffff !important;
  border: 1px solid #e2e8f0 !important;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.04) !important;
  color: #0f172a !important;
}
[data-theme="light"] .edu-card-heading {
  color: #0f172a !important;
}
[data-theme="light"] .edu-card-sub {
  color: #64748b !important;
}
[data-theme="light"] .edu-data-row span {
  color: #64748b !important;
}
[data-theme="light"] .edu-data-row strong {
  color: #0f172a !important;
}
[data-theme="light"] .edu-data-row {
  border-bottom: 1px solid #f1f5f9 !important;
}
[data-theme="light"] .edu-doc-item,
[data-theme="light"] .edu-doc-row {
  background: #f8fafc !important;
  border: 1px solid #e2e8f0 !important;
}
[data-theme="light"] .edu-doc-title {
  color: #0f172a !important;
}
[data-theme="light"] .edu-modal-box {
  background: #ffffff !important;
  border: 1px solid #e2e8f0 !important;
  color: #0f172a !important;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.12) !important;
}
[data-theme="light"] .edu-modal-head h3 {
  color: #0f172a !important;
}
[data-theme="light"] .edu-modal-body p {
  color: #475569 !important;
}


/* ENHANCED COUNSELLING & PREFERENCES STYLING */
.edu-pref-builder { margin-top: 16px; display: flex; flex-direction: column; gap: 12px; }
.edu-pref-item { display: flex; align-items: center; justify-content: space-between; padding: 12px 18px; background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 12px; transition: 0.2s; }
.edu-pref-item:hover { border-color: rgba(255,255,255,0.18); background: rgba(255,255,255,0.05); }
.edu-pref-order-badge { font-size: 1.1rem; font-weight: 700; color: #c2882f; min-width: 44px; display: flex; align-items: center; gap: 4px; }
.edu-pref-info { flex: 1; padding: 0 16px; }
.edu-pref-college { font-weight: 600; color: #f8fafc; font-size: 0.98rem; }
.edu-pref-program { font-size: 0.88rem; color: #94a3b8; margin-top: 2px; }
.edu-pref-controls { display: flex; gap: 8px; align-items: center; }
.edu-btn-order { background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.12); color: #cbd5e1; border-radius: 8px; width: 34px; height: 34px; display: flex; align-items: center; justify-content: center; cursor: pointer; transition: 0.2s; font-size: 14px; }
.edu-btn-order:hover { background: rgba(255,255,255,0.18); color: #fff; }
.edu-btn-order:disabled { opacity: 0.3; cursor: not-allowed; }
.edu-btn-remove { background: rgba(239,68,68,0.1); border: 1px solid rgba(239,68,68,0.3); color: #ef4444; border-radius: 8px; width: 34px; height: 34px; display: flex; align-items: center; justify-content: center; cursor: pointer; transition: 0.2s; }
.edu-btn-remove:hover { background: #ef4444; color: #fff; }
.edu-pref-add-row { display: flex; gap: 12px; margin-top: 10px; align-items: center; }
.edu-pref-select { flex: 1; }
.edu-btn-float { background: #6366f1; color: #fff; border: none; padding: 10px 18px; border-radius: 10px; font-weight: 600; cursor: pointer; transition: 0.2s; display: inline-flex; align-items: center; gap: 6px; }
.edu-btn-float:hover { background: #4f46e5; }
.edu-btn-withdraw-link { background: transparent; border: 1px solid rgba(239,68,68,0.4); color: #ef4444; padding: 8px 14px; border-radius: 8px; font-weight: 600; cursor: pointer; transition: 0.2s; display: inline-flex; align-items: center; gap: 6px; font-size: 0.85rem; }
.edu-btn-withdraw-link:hover { background: #ef4444; color: #fff; }
.edu-locked-tag { font-size: 0.8rem; background: rgba(100,116,139,0.25); border: 1px solid rgba(100,116,139,0.35); color: #94a3b8; padding: 4px 10px; border-radius: 8px; display: inline-flex; align-items: center; gap: 4px; }
.edu-lock-banner { padding: 14px 18px; border-radius: 12px; margin-bottom: 18px; display: flex; align-items: center; gap: 12px; font-size: 0.95rem; }
.edu-lock-banner-info { background: rgba(59,130,246,0.1); border: 1px solid rgba(59,130,246,0.25); color: #60a5fa; }
.edu-lock-banner-warn { background: rgba(245,158,11,0.1); border: 1px solid rgba(245,158,11,0.25); color: #fbbf24; }
.edu-lock-banner-success { background: rgba(16,185,129,0.1); border: 1px solid rgba(16,185,129,0.25); color: #34d399; }


/* ENHANCED PREFERENCE BUILDER - LIGHT & DARK THEMES */
.edu-pref-builder { margin-top: 16px; display: flex; flex-direction: column; gap: 12px; }
.edu-pref-item {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  padding: 14px 18px !important;
  background: rgba(255, 255, 255, 0.04) !important;
