}
[data-theme="light"] .edu-btn-order {
  background: #f1f5f9 !important;
  border: 1px solid #cbd5e1 !important;
  color: #334155 !important;
}
[data-theme="light"] .edu-btn-order:hover:not(:disabled) {
  background: #6366f1 !important;
