  align-items: center !important;
}
.edu-pref-select {
  flex: 1 !important;
  height: 44px !important;
  padding: 8px 14px !important;
  border-radius: 10px !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  outline: none !important;
  background: #0f172a !important;
  color: #ffffff !important;
  border: 1.5px solid #334155 !important;
  transition: all 0.2s !important;
}
.edu-pref-select:focus {
  border-color: #6366f1 !important;
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.25) !important;
}
.edu-pref-select option {
  background: #0f172a !important;
  color: #ffffff !important;
  padding: 8px !important;
}
[data-theme="light"] .edu-pref-select {
  background: #ffffff !important;
  color: #0f172a !important;
  border: 1.5px solid #cbd5e1 !important;
}
[data-theme="light"] .edu-pref-select:focus {
  border-color: #6366f1 !important;
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.15) !important;
}
[data-theme="light"] .edu-pref-select option {
  background: #ffffff !important;
  color: #0f172a !important;
}
.edu-btn-add-choice {
  background: linear-gradient(135deg, #6366f1, #4f46e5) !important;
  color: #ffffff !important;
  border: none !important;
  height: 44px !important;
  padding: 0 20px !important;
  border-radius: 10px !important;
  font-weight: 700 !important;
  font-size: 14px !important;
  cursor: pointer !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 6px !important;
  transition: all 0.2s !important;
  white-space: nowrap !important;
}
.edu-btn-add-choice:hover:not(:disabled) {
  background: linear-gradient(135deg, #4f46e5, #4338ca) !important;
  transform: translateY(-1px) !important;
  box-shadow: 0 4px 12px rgba(99, 102, 241, 0.35) !important;
}
.edu-btn-add-choice:disabled {
  opacity: 0.5 !important;
  cursor: not-allowed !important;
  transform: none !important;
}

sp_widget.script:
(function() {
  data.isLoggedIn = gs.isLoggedIn();
  data.userName = gs.getUserDisplayName() || gs.getUserName();
  data.userInitial = data.userName ? data.userName.charAt(0).toUpperCase() : 'U';
  data.hasApplication = false;
  data.app = {};
  data.student = {};
  data.requiredDocs = [];
  data.counselling = {
    hasCounselling: false,
    round1: null,
    round2: null,
    round1_published: true,
    round2_enabled: false,
    round2_published: false
  };

  if (!data.isLoggedIn) return;

  var userEmail = gs.getUser().getEmail();
  var userName = gs.getUserName();

  // Helper to map category
  function mapCategoryToStudentChoice(admCat) {
    if (!admCat) return 'GEN';
    var c = admCat.toString().toLowerCase().trim();
    if (c === 'gen' || c === 'general') return 'GEN';
    if (c.indexOf('backward') > -1 || c.indexOf('obc') > -1) return 'OBC';
    if (c.indexOf('economically') > -1 || c.indexOf('ews') > -1) return 'EWS';
    if (c.indexOf('disability') > -1 || c.indexOf('pwd') > -1) return 'PwD';
    if (c.indexOf('sc') > -1 || c.indexOf('st') > -1) return 'SC/ST';
    return 'GEN';
  }

  // 1. Find active application by email OR sys_created_by
  var grApp = new GlideRecord('x_1790229_edusph_0_admission_application');
  var qc = grApp.addQuery('sys_created_by', userName);
  if (userEmail) {
    qc.addOrCondition('email', userEmail);
  }
  grApp.orderByDesc('sys_created_on');
  grApp.setLimit(1);
  grApp.query();

  if (grApp.next()) {
    data.hasApplication = true;
    var appSysId = grApp.getUniqueValue();

    // Calculate or retrieve merit score
    var dbMerit = parseFloat(grApp.getValue('merit_score')) || 0;
    var m10 = parseFloat(grApp.getValue('class_10_percentage')) || 0;
    var m12 = parseFloat(grApp.getValue('class_12_percentage')) || 0;
    var jee = parseFloat(grApp.getValue('jee_score')) || 0;
    var displayMerit = "Pending Calculation";
    if (dbMerit > 0) {
      displayMerit = dbMerit.toFixed(2);
    } else if (m10 > 0 && m12 > 0 && jee > 0) {
      displayMerit = ((m10 + m12 + jee) / 3).toFixed(2);
    }

    var progName = grApp.program.name ? grApp.program.name.toString() : grApp.program.getDisplayValue();
    var colName = grApp.college.name ? grApp.college.name.toString() : grApp.college.getDisplayValue();

    data.app = {
      sys_id: appSysId,
      app_no: grApp.getValue('app_no') || '',
      name: grApp.getValue('name') || '',
      category: grApp.getValue('category') || 'general',
      college_name: colName || 'Netaji Subhas Institute of Technology',
      program_name: progName || 'B.Tech Computer Science & Eng.',
      status: grApp.getValue('status') || 'draft',
      applied_on: grApp.getValue('applied_on') || grApp.getValue('sys_created_on') || '',
      created_on: grApp.getValue('sys_created_on') || '',
      class_10_percentage: grApp.getValue('class_10_percentage') || '0',
      class_12_percentage: grApp.getValue('class_12_percentage') || '0',
      jee_score: grApp.getValue('jee_score') || '0',
      merit_score: displayMerit,
      allocation_round: grApp.getValue('allocation_round') || '1'
    };

    // Read system properties for counselling rounds
    var r1Active = gs.getProperty('x_1790229_edusph_0.counselling.round1_active', 'true') === 'true';
    var r1Pub = gs.getProperty('x_1790229_edusph_0.counselling.round1_published', 'true') === 'true';
    var r2Enabled = gs.getProperty('x_1790229_edusph_0.counselling.round2_enabled', 'false') === 'true';
    var r2Pub = gs.getProperty('x_1790229_edusph_0.counselling.round2_published', 'false') === 'true';

    data.counselling.round1_published = r1Pub;
    data.counselling.round2_enabled = r2Enabled;
    data.counselling.round2_published = r2Pub;

    // Check if in merit or offered or accepted
    var st = (data.app.status || '').toLowerCase().trim();
    var isMeritOrAbove = (st === 'in_merit' || st === 'offered' || st === 'accepted');


    // Schedule and phase integration
    var schedSvc = new x_1790229_edusph_0.CounsellingScheduleService();
    data.schedule = schedSvc.getActiveConfig();
    data.phase = schedSvc.getCurrentPhase();

    // Dynamic document locking logic
    data.docsLocked = true;
    data.docStatusMessage = "";
    data.docMessageType = "info";

    var curSt = (data.app.status || '').toLowerCase().trim();
    if (curSt === 'submitted') {
      data.docsLocked = true;
      data.docMessageType = "info";
      data.docStatusMessage = "Your application has been submitted successfully. Please wait while the administration reviews your application.";
    } else if (curSt === 'document_pending') {
      data.docsLocked = false;
      data.docMessageType = "warn";
      data.docStatusMessage = "Your application has been reviewed. Please upload the required documents.";
      if (grApp.getValue('correction_reason')) {
        data.docStatusMessage += " Remarks: " + grApp.getValue('correction_reason');
      }
    } else if (curSt === 'verified' || curSt === 'in_merit') {
      data.docsLocked = true;
      data.docMessageType = "success";
      data.docStatusMessage = "Your application has been verified successfully. Please wait for the counselling process to begin.";
    }

    // Load Student Preferences
    data.preferences = [];
    var pGr = new GlideRecord('x_1790229_edusph_0_counselling_preference');
    pGr.addQuery('application', appSysId);
    pGr.addQuery('active', true);
    pGr.orderBy('preference_order');
    pGr.query();
    while (pGr.next()) {
      var prefCol = pGr.college.name ? pGr.college.name.toString() : pGr.college.getDisplayValue();
      var prefProg = pGr.program.name ? pGr.program.name.toString() : pGr.program.getDisplayValue();
      data.preferences.push({
        sys_id: pGr.getUniqueValue(),
        preference_order: parseInt(pGr.getValue('preference_order')) || 1,
        college_id: pGr.getValue('college'),
        college_name: prefCol,
        program_id: pGr.getValue('program'),
        program_name: prefProg,
        locked: pGr.getValue('locked') === '1' || pGr.getValue('locked') === true
      });
    }

    // Load Eligible Programs for Preference Selection
    data.eligiblePrograms = [];
    var cpGr = new GlideRecord('x_1790229_edusph_0_coll_prog');
    cpGr.addQuery('approved', true);
    cpGr.query();
    var sMerit = parseFloat(data.app.merit_score) || 0;
    while (cpGr.next()) {
      var pCut = parseFloat(cpGr.getValue('merit_cutoff')) || 50.0;
      var cId = cpGr.getValue('college');
      var prId = cpGr.getValue('program');
      var cName = cpGr.college.name ? cpGr.college.name.toString() : cpGr.college.getDisplayValue();
      var prName = cpGr.program.name ? cpGr.program.name.toString() : cpGr.program.getDisplayValue();
      data.eligiblePrograms.push({
        college_id: cId,
        college_name: cName,
        program_id: prId,
        program_name: prName,
        cutoff: pCut,
        intake: parseInt(cpGr.getValue('intake_seats')) || 60,
        eligible: (sMerit >= pCut || curSt === 'in_merit')
      });
    }

    // 2. Fetch / Ensure Round 1 Allotment Record
    var r1Gr = new GlideRecord('x_1790229_edusph_0_counselling_allotment');
    r1Gr.addQuery('application', appSysId);
    r1Gr.addQuery('round', 1);
    r1Gr.setLimit(1);
    r1Gr.query();

    if (r1Gr.next()) {
      var r1Col = r1Gr.allotted_college.name ? r1Gr.allotted_college.name.toString() : r1Gr.allotted_college.getDisplayValue();
      var r1Prog = r1Gr.allotted_program.name ? r1Gr.allotted_program.name.toString() : r1Gr.allotted_program.getDisplayValue();
      data.counselling.round1 = {
        sys_id: r1Gr.getUniqueValue(),
        round: 1,
        college_name: r1Col || data.app.college_name,
        program_name: r1Prog || data.app.program_name,
        category: r1Gr.getValue('allotted_category') || data.app.category,
        status: r1Gr.getValue('status') || 'Action Required',
        allotment_date: r1Gr.getValue('allotment_date') || data.app.applied_on,
        acceptance_deadline: r1Gr.getValue('acceptance_deadline') || '',
        decision: r1Gr.getValue('decision') || 'Pending',
        decision_date: r1Gr.getValue('decision_date') || '',
        is_eligible: r1Gr.getValue('is_eligible') == '1' || r1Gr.getValue('is_eligible') === true
      };
      data.counselling.hasCounselling = true;
    } else if (isMeritOrAbove) {
      // Create initial Round 1 record for backward compatibility
      r1Gr.initialize();
      r1Gr.setValue('application', appSysId);
      r1Gr.setValue('round', 1);
      r1Gr.setValue('allotted_college', grApp.getValue('college'));
      r1Gr.setValue('allotted_program', grApp.getValue('program'));
      r1Gr.setValue('allotted_category', data.app.category || 'general');
      r1Gr.setValue('allotment_date', new GlideDateTime().getDate().getByFormat('yyyy-MM-dd'));
      r1Gr.setValue('is_eligible', true);
      r1Gr.setValue('active', true);

      var initStatus = 'Action Required';
      var initDecision = 'Pending';
      if (st === 'accepted') {
        initStatus = 'Seat Accepted';
        initDecision = 'Accepted';
      }
      r1Gr.setValue('status', initStatus);
      r1Gr.setValue('decision', initDecision);
      var r1Id = r1Gr.insert();

      data.counselling.round1 = {
        sys_id: r1Id,
        round: 1,
        college_name: data.app.college_name,
        program_name: data.app.program_name,
        category: data.app.category,
        status: initStatus,
        allotment_date: new GlideDateTime().getDate().getByFormat('yyyy-MM-dd'),
        acceptance_deadline: '',
        decision: initDecision,
        decision_date: '',
        is_eligible: true
      };
      data.counselling.hasCounselling = true;
    }

    // 3. Fetch Round 2 Allotment Record if exists
    var r2Gr = new GlideRecord('x_1790229_edusph_0_counselling_allotment');
    r2Gr.addQuery('application', appSysId);
    r2Gr.addQuery('round', 2);
    r2Gr.setLimit(1);
    r2Gr.query();

    if (r2Gr.next()) {
      var r2Col = r2Gr.allotted_college.name ? r2Gr.allotted_college.name.toString() : r2Gr.allotted_college.getDisplayValue();
      var r2Prog = r2Gr.allotted_program.name ? r2Gr.allotted_program.name.toString() : r2Gr.allotted_program.getDisplayValue();
      data.counselling.round2 = {
        sys_id: r2Gr.getUniqueValue(),
        round: 2,
        college_name: r2Col || data.app.college_name,
        program_name: r2Prog || data.app.program_name,
        category: r2Gr.getValue('allotted_category') || data.app.category,
        status: r2Gr.getValue('status') || 'Action Required',
        allotment_date: r2Gr.getValue('allotment_date') || '',
        acceptance_deadline: r2Gr.getValue('acceptance_deadline') || '',
        decision: r2Gr.getValue('decision') || 'Pending',
        decision_date: r2Gr.getValue('decision_date') || '',
        is_eligible: r2Gr.getValue('is_eligible') == '1' || r2Gr.getValue('is_eligible') === true
      };
      data.counselling.hasCounselling = true;
    }

    // 4. If accepted / enrolled, fetch student record
    if (st === 'accepted' || st === 'enrolled') {
      var grStu = new GlideRecord('x_1790229_edusph_0_student');
      grStu.addQuery('admission_application', appSysId);
      grStu.setLimit(1);
      grStu.query();
      if (grStu.next()) {
        data.student = {
          sys_id: grStu.getUniqueValue(),
          roll_no: grStu.getValue('roll_no') || '',
          category: grStu.getValue('category') || '',
          status: grStu.getValue('status') || 'Active',
          admitted_on: grStu.getValue('admitted_on') || ''
        };
      }
    }

    // 5. Dynamic category document definitions
    var baseDocs = [
      { type: 'Class 10 Marksheet', label: '10th Marksheet / DOB Proof', isCategory: false },
      { type: 'Class 12 Marksheet', label: '12th Marksheet', isCategory: false },
      { type: 'Aadhaar Card', label: 'Aadhaar / National ID Card', isCategory: false },
      { type: 'Passport Photo', label: 'Passport Photograph', isCategory: false },
      { type: 'Transfer Certificate', label: 'Transfer Certificate (TC)', isCategory: false }
    ];

    var cat = (data.app.category || '').toLowerCase();
    if (cat.indexOf('backward') > -1 || cat.indexOf('obc') > -1) {
      baseDocs.push({ type: 'OBC Category Certificate', label: 'Caste Certificate (OBC-NCL)', isCategory: true });
    } else if (cat.indexOf('economically') > -1 || cat.indexOf('ews') > -1) {
      baseDocs.push({ type: 'Income Certificate', label: 'Income & Asset Certificate (EWS)', isCategory: true });
    } else if (cat.indexOf('disability') > -1 || cat.indexOf('pwd') > -1) {
      baseDocs.push({ type: 'PwD Disability Certificate', label: 'Disability Certificate (PwD)', isCategory: true });
    } else if (cat.indexOf('defen') > -1) {
      baseDocs.push({ type: 'Defence Certificate', label: 'Defence Priority Certificate', isCategory: true });
    }

    // Documents status check
    for (var k = 0; k < baseDocs.length; k++) {
      var d = baseDocs[k];
      var grDoc = new GlideRecord('x_1790229_edusph_0_student_document');
      grDoc.addQuery('application', appSysId);
      grDoc.addQuery('doc_type', d.type);
      grDoc.setLimit(1);
      grDoc.query();

      var docSysId = '';
      if (grDoc.next()) {
        docSysId = grDoc.getUniqueValue();
        d.verify_status = grDoc.getValue('verify_status') || 'Pending';
        d.rejection_reason = grDoc.getValue('rejection_reason') || '';
      } else {
        grDoc.initialize();
        grDoc.setValue('application', appSysId);
        grDoc.setValue('doc_type', d.type);
        grDoc.setValue('verify_status', 'Pending');
        docSysId = grDoc.insert();
        d.verify_status = 'Pending';
        d.rejection_reason = '';
      }
      d.sys_id = docSysId;

      var grAtt = new GlideRecord('sys_attachment');
      grAtt.addQuery('table_name', 'x_1790229_edusph_0_student_document');
      grAtt.addQuery('table_sys_id', docSysId);
      grAtt.orderByDesc('sys_created_on');
      grAtt.setLimit(1);
      grAtt.query();
      if (grAtt.next()) {
        d.uploaded = true;
        d.fileName = grAtt.getValue('file_name');
        d.attSysId = grAtt.getUniqueValue();
      } else {
        d.uploaded = false;
        d.fileName = '';
        d.attSysId = '';
      }
      data.requiredDocs.push(d);
    }
  }

  // ACTION: Accept Counselling Allotment (Round 1 or Round 2)
  if (input && input.action === 'accept_counselling_allotment') {
    var roundNum = input.round || 1;
    var aId = input.appSysId;

    // 1. Update counselling_allotment
    var allGr = new GlideRecord('x_1790229_edusph_0_counselling_allotment');
    allGr.addQuery('application', aId);
    allGr.addQuery('round', roundNum);
    allGr.query();
    if (allGr.next()) {
      allGr.setValue('status', 'Seat Accepted');
      allGr.setValue('decision', 'Accepted');
      allGr.setValue('decision_date', new GlideDateTime().getDisplayValue());
      allGr.update();
    }

    // 2. Update admission_application
    var appUp = new GlideRecord('x_1790229_edusph_0_admission_application');
    if (appUp.get(aId)) {
      var finalColId = (allGr.isValidRecord() && allGr.getValue('allotted_college')) ? allGr.getValue('allotted_college') : appUp.getValue('college');
      var finalProgId = (allGr.isValidRecord() && allGr.getValue('allotted_program')) ? allGr.getValue('allotted_program') : appUp.getValue('program');

      appUp.setValue('status', 'accepted');
      appUp.setValue('counselling_state', 'Seat Accepted');
      if (finalColId) appUp.setValue('college', finalColId);
      if (finalProgId) appUp.setValue('program', finalProgId);
      appUp.update();

      // 3. Create / Update Student Record
      var grNewStudent = new GlideRecord('x_1790229_edusph_0_student');
      grNewStudent.addQuery('admission_application', aId);
      grNewStudent.query();
      var studentId = '';
      var rollNo = '';
      var studentCategory = mapCategoryToStudentChoice(appUp.getValue('category'));

      if (grNewStudent.next()) {
        studentId = grNewStudent.getUniqueValue();
        rollNo = grNewStudent.getValue('roll_no');
      } else {
        grNewStudent.initialize();
        grNewStudent.setValue('user', gs.getUserID());
        grNewStudent.setValue('college', finalColId);
        grNewStudent.setValue('program', finalProgId);
        grNewStudent.setValue('category', studentCategory);
        grNewStudent.setValue('admission_application', aId);
        grNewStudent.setValue('admitted_on', new GlideDateTime().getDate().getByFormat('yyyy-MM-dd'));
        grNewStudent.setValue('status', 'Active');

        var colCode = 'NSIT';
        var finalColGr = new GlideRecord('x_1790229_edusph_0_college');
        if (finalColGr.get(finalColId) && finalColGr.getValue('code')) {
          colCode = finalColGr.getValue('code').split('-')[0];
        }

        var progCode = 'CSE';
        var finalProgGr = new GlideRecord('x_1790229_edusph_0_program');
        if (finalProgGr.get(finalProgId) && finalProgGr.getValue('code')) {
          progCode = finalProgGr.getValue('code').replace('BTECH-', '').replace('MTECH-', '');
        }

        var randNum = Math.floor(100 + Math.random() * 900);
        rollNo = colCode + '-2026-' + progCode + '-' + randNum;
        grNewStudent.setValue('roll_no', rollNo);

        var grSec = new GlideRecord('x_1790229_edusph_0_section');
        grSec.addQuery('college', finalColId);
        grSec.setLimit(1);
        grSec.query();
        if (grSec.next()) {
          grNewStudent.setValue('section', grSec.getUniqueValue());
        }
        studentId = grNewStudent.insert();
      }

      // Link all student documents
      if (studentId) {
        var grLinkDocs = new GlideRecord('x_1790229_edusph_0_student_document');
        grLinkDocs.addQuery('application', aId);
        grLinkDocs.query();
        while (grLinkDocs.next()) {
          grLinkDocs.setValue('student', studentId);
          grLinkDocs.update();
        }
      }

      data.accepted = true;
      data.newRollNo = rollNo;
      data.student = {
        sys_id: studentId,
        roll_no: rollNo,
        category: studentCategory,
        status: 'Active'
      };
    }
  }

  // ACTION: Reject Counselling Allotment
  if (input && input.action === 'reject_counselling_allotment') {
    var rejRound = input.round || 1;
    var rejAppId = input.appSysId;

    var rejAll = new GlideRecord('x_1790229_edusph_0_counselling_allotment');
    rejAll.addQuery('application', rejAppId);
    rejAll.addQuery('round', rejRound);
    rejAll.query();
    if (rejAll.next()) {
      rejAll.setValue('status', 'Seat Rejected');
      rejAll.setValue('decision', 'Rejected');
      rejAll.setValue('decision_date', new GlideDateTime().getDisplayValue());
      rejAll.update();
    }

    var appRej = new GlideRecord('x_1790229_edusph_0_admission_application');
    if (appRej.get(rejAppId)) {
      appRej.setValue('counselling_state', 'Seat Rejected');
      appRej.update();
    }
    data.rejected = true;
  }


  // ACTION: Save Preferences
  if (input && input.action === 'save_preferences') {
    var prefs = input.preferences || [];
    var delP = new GlideRecord('x_1790229_edusph_0_counselling_preference');
    delP.addQuery('application', input.appSysId);
    delP.query();
    while (delP.next()) {
      delP.deleteRecord();
    }
    for (var pi = 0; pi < prefs.length; pi++) {
      var np = new GlideRecord('x_1790229_edusph_0_counselling_preference');
      np.initialize();
      np.setValue('application', input.appSysId);
      np.setValue('college', prefs[pi].college_id);
      np.setValue('program', prefs[pi].program_id);
      np.setValue('preference_order', pi + 1);
      np.setValue('locked', true);
      np.setValue('active', true);
      np.insert();
    }
    data.preferencesSaved = true;
  }

  // ACTION: Float Allotment
  if (input && input.action === 'float_counselling_allotment') {
    var fltAll = new GlideRecord('x_1790229_edusph_0_counselling_allotment');
    fltAll.addQuery('application', input.appSysId);
    fltAll.addQuery('round', input.round || 1);
    fltAll.query();
    if (fltAll.next()) {
      fltAll.setValue('decision', 'Float');
      fltAll.setValue('decision_date', new GlideDateTime().getDisplayValue());
      fltAll.setValue('remarks', 'Seat Retained. Participating in Round 2 for higher preference upgrade.');
      fltAll.update();
    }
    data.floated = true;
  }

  // ACTION: Withdraw Admission
  if (input && input.action === 'withdraw_admission') {
    var wAll = new GlideRecord('x_1790229_edusph_0_counselling_allotment');
    wAll.addQuery('application', input.appSysId);
    wAll.query();
    while (wAll.next()) {
      wAll.setValue('status', 'Withdrawn');
      wAll.setValue('decision', 'Withdrawn');
      wAll.setValue('withdrawal_date', new GlideDateTime().getDisplayValue());
      wAll.setValue('withdrawal_reason', input.reason || 'Student requested withdrawal');
      wAll.update();
    }
    var wApp = new GlideRecord('x_1790229_edusph_0_admission_application');
    if (wApp.get(input.appSysId)) {
      wApp.setValue('status', 'withdrawn');
      wApp.setValue('withdrawal_on', new GlideDate().getValue());
      wApp.update();
    }
    var wStu = new GlideRecord('x_1790229_edusph_0_student');
    wStu.addQuery('admission_application', input.appSysId);
    wStu.query();
    if (wStu.next()) {
      wStu.setValue('status', 'Withdrawn');
      wStu.update();
    }
    data.withdrawn = true;
  }

  // Handle Mark Doc Uploaded Notification from Client
  if (input && input.action === 'mark_doc_uploaded') {
    var upDocGR = new GlideRecord('x_1790229_edusph_0_student_document');
    if (upDocGR.get(input.doc_sys_id)) {
      if (upDocGR.getValue('verify_status') !== 'Verified') {
        upDocGR.setValue('verify_status', 'Pending');
        upDocGR.update();
        data.updated = true;
      }
    }
  }

  // Correction Request
  if (input && input.action === 'submit_correction') {
    var cApp = new GlideRecord('x_1790229_edusph_0_admission_application');
    if (cApp.get(input.appSysId)) {
      cApp.setValue('correction_reason', input.reason);
      cApp.update();
      data.correctionSubmitted = true;
    }
  }
})();
